// Open IndexedDB and store
const req = indexedDB.open('BLWatchlistDB', 1);
req.onupgradeneeded = (e) => {
  const db = e.target.result;
  if (!db.objectStoreNames.contains('appState')) {
    db.createObjectStore('appState');
  }
};
req.onsuccess = (e) => {
  const db = e.target.result;
  const tx = db.transaction(['appState'], 'readwrite');
  const store = tx.objectStore('appState');
  const state = {
    version: 1,
    data: {
      entries: TEST_ENTRIES,
      ongoing: [],
      favorites: [],
      top10Drawers: []
    },
    savedAt: Date.now()
  };
  store.put(state, 'bl-watchlist-data');
  tx.oncomplete = () => {
    db.close();
    console.log('Test data injected: 100 entries (~7.4 MB)');
    window.location.reload();
  };
};
